$s=$c->prepare("SELECT p.*,pr.nome_preferencia,v.publicada_em FROM publicacao_obra p LEFT JOIN preferencia pr ON pr.id_preferencia=p.id_genero LEFT JOIN versao_publicacao v ON v.id=p.id_versao_atual WHERE p.id_autor=? AND p.estado<>'excluido' AND (?='' OR p.estado=?) AND (?='' OR p.titulo ILIKE ?) ORDER BY p.atualizado_em DESC");$s->execute([$user,$status,$status,$q,'%'.$q.'%']);$obras=$s->fetchAll();
